  1	library(readr)
  2	library(rstan)
  3	library(posterior)
  4	library(jsonlite)
  5	
  6	stan_code <- "
  7	functions {
  8	  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
  9	    int N = rows(X);
 10	    int D = cols(X);
 11	    matrix[N, N] K;
 12	
 13	    for (i in 1:N) {
 14	      K[i, i] = square(alpha) + jitter;
 15	      for (j in (i + 1):N) {
 16	        real s = 0;
 17	        for (d in 1:D) {
 18	          real t = (X[i, d] - X[j, d]) / rho[d];
 19	          s += t * t;
 20	        }
 21	        K[i, j] = square(alpha) * exp(-0.5 * s);
 22	        K[j, i] = K[i, j];
 23	      }
 24	    }
 25	    return K;
 26	  }
 27	
 28	  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
 29	    int N = rows(X);
 30	    int M = rows(X_new);
 31	    int D = cols(X); // == cols(X_new)
 32	    matrix[N, M] Kx;
 33	    for (i in 1:N) {
 34	      for (j in 1:M) {
 35	        real s = 0;
 36	        for (d in 1:D) {
 37	          real t = (X[i, d] - X_new[j, d]) / rho[d];
 38	          s += t * t;
 39	        }
 40	        Kx[i, j] = square(alpha) * exp(-0.5 * s);
 41	      }
 42	    }
 43	    return Kx;
 44	  }
 45	}
 46	
 47	data {
 48	  int<lower=1> N;
 49	  int<lower=1> D;
 50	  matrix[N, D] X;
 51	  int<lower=1> P;
 52	  matrix[N, P] H;
 53	  vector[N] y;
 54	  real<lower=0> jitter;
 55	
 56	  int<lower=0> N_new;
 57	  matrix[N_new, D] X_new;
 58	  matrix[N_new, P] H_new;
 59	}
 60	
 61	parameters {
 62	  vector[P] beta;
 63	  real<lower=0> alpha;
 64	  vector<lower=0>[D] rho;
 65	  real<lower=0> sigma;
 66	}
 67	
 68	transformed parameters {
 69	  vector[N] mu = H * beta;
 70	  matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
 71	                   + diag_matrix(rep_vector(square(sigma), N));
 72	  matrix[N, N] L_K = cholesky_decompose(K);
 73	}
 74	
 75	model {
 76	  beta  ~ normal(0, 1);
 77	  alpha ~ normal(0, 1.5);
 78	  rho   ~ lognormal(0, 1);
 79	  sigma ~ normal(0, 0.5);
 80	  y ~ multi_normal_cholesky(mu, L_K);
 81	}
 82	
 83	generated quantities {
 84	  vector[N_new] y_new;
 85	  if (N_new > 0) {
 86	    matrix[N, N_new] K_x_xnew = cross_cov_ard(X, X_new, rho, alpha);
 87	    matrix[N_new, N_new] K_new = cov_ard_sqexp(X_new, rho, alpha, jitter);
 88	    vector[N] resid = y - (H * beta);
 89	
 90	    vector[N] alpha_vec = mdivide_left_tri_low(L_K, resid);
 91	    alpha_vec = mdivide_left_tri_low(L_K', alpha_vec);
 92	
 93	    vector[N_new] f_mean = (K_x_xnew' * alpha_vec);
 94	    matrix[N, N_new] v = mdivide_left_tri_low(L_K, K_x_xnew);
 95	    vector[N_new] f_var = to_vector(diagonal(K_new)) - to_vector(columns_dot_self(v));
 96	    for (m in 1:N_new) {
 97	      real m_mean = (H_new[m] * beta) + f_mean[m];
 98	      real m_sd   = sqrt(f_var[m] + square(sigma));
 99	      y_new[m] = normal_rng(m_mean, m_sd);
100	    }
101	  }
102	}
103	"
104	
105	writeLines(stan_code, "gp_ard_regression.stan")
106	
107	meta_pub <- jsonlite::fromJSON("meta_public.json")
108	train_X <- read_csv("train_X.csv")
109	test_X <- read_csv("test_X.csv")
110	train_y <- read_csv("train_y.csv")
111	train_X <- as.matrix(train_X)
112	test_X <- as.matrix(test_X)
113	train_y <- train_y$y
114	
115	P <- as.integer(meta_pub$P)
116	jitter <- as.numeric(meta_pub$jitter)
117	
118	N <- nrow(train_X); D <- ncol(train_X)
119	N_new <- nrow(test_X)
120	
121	H <- cbind(1, train_X[,1], train_X[,2])
122	H_new <- if (N_new > 0) cbind(1, test_X[,1], test_X[,2]) else matrix(0, 0, P)
123	
124	data_list <- list(
125	  N = N, D = D, X = train_X,
126	  P = P, H = H, y = train_y,
127	  jitter = jitter,
128	  N_new = N_new,
129	  X_new = if (N_new > 0) test_X else matrix(0, 0, D),
130	  H_new = if (N_new > 0) H_new else matrix(0, 0, P)
131	)
132	
133	sm <- stan_model("gp_ard_regression.stan")
134	fit <- sampling(
135	  sm, data = data_list,
136	  chains = 4, iter = 2000, warmup = 1000, thin = 2,
137	  seed = 1,
138	  control = list(
139	    adapt_delta = 0.93,
140	    max_treedepth = 14,
141	    adapt_gamma = 0.05,
142	    adapt_kappa = 0.75,
143	    adapt_t0 = 10,
144	    adapt_init_buffer = 100,
145	    adapt_term_buffer = 50,
146	    adapt_window = 25
147	  ),
148	  init_r = 0.1,
149	  save_warmup = FALSE,
150	  refresh = 200
151	)
152	
153	post <- rstan::extract(fit)
154	alpha_post <- mean(post$alpha)
155	sigma_post <- mean(post$sigma)
156	rho_post <- colMeans(post$rho)
157	beta_post <- colMeans(post$beta)
158	
159	cat("Posterior means:\n")
160	cat("alpha:", alpha_post, "\n")
161	cat("sigma:", sigma_post, "\n")
162	cat("rho:  ", paste(round(rho_post, 6), collapse = " "), "\n")
163	cat("beta: ", paste(round(beta_post, 6), collapse = " "), "\n")

